{"source":"#include <stdio.h>
#include <stdlib.h>

long long removeZero(long long a);

int main(int argc, char *argv[])
{
    long long a,b,c1,c2;

    scanf("%lld",&a);
    scanf("%lld",&b);
    c1 = a + b;


    a = removeZero(a);
    b = removeZero(b);
    c2 = removeZero(c1);
    if(a+b==c2)
    {
        printf("YES");
    }
    else
    {
        printf("NO");
    }

    return 0;
}



long long removeZero(long long a)
{
    long long num=0;
    long long mult=1;

    while(a != 0)
    {
        long long d = a % 10;
        if(d != 0)
        {
            num = num + d * mult;
            mult = mult * 10;
        }
        a = a/10;
    }

    return num;
}"}
